/**
 * @name Path traversal vulnerability
 * @description File operations with untrusted input can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    )
    or
    // os.path operations
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename", "stat", "chmod", "chown"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // shutil operations
    exists(API::CallNode call |
      call = API::moduleImport("shutil").getMember(["copy", "move", "rmtree"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name ReDoS with untrusted input
 * @description Regular expression denial of service with user-controlled input
 * @kind path-problem
 * @problem.severity high
 * @id py/redos-taint
 * @tags security
 *        external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Regex operations that could be vulnerable to ReDoS
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember(["search", "match", "findall", "finditer", "sub", "subn", "split", "compile"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module ReDoSFlow = TaintTracking::Global<ReDoSConfig>;
import ReDoSFlow::PathGraph

from ReDoSFlow::PathNode source, ReDoSFlow::PathNode sink
where ReDoSFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "ReDoS vulnerability: user input reaches regex operation $@.", source.getNode(), "user input"

/**
 * @name Server-Side Request Forgery (SSRF)
 * @description Making HTTP requests with user-controlled URLs can lead to SSRF attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // HTTP requests via urllib.request.urlopen
    exists(API::CallNode call |
      call = API::moduleImport("urllib").getMember("request").getMember("urlopen").getACall() and
      sink = call.getArg(0)
    )
    or
    // HTTP requests via requests.get/post
    exists(API::CallNode call |
      call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "head", "options", "patch"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // HTTP requests via httpx
    exists(API::CallNode call |
      call = API::moduleImport("httpx").getMember(["get", "post", "put", "delete", "head", "options", "patch"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SsrfFlow = TaintTracking::Global<SsrfConfig>;
import SsrfFlow::PathGraph

from SsrfFlow::PathNode source, SsrfFlow::PathNode sink
where SsrfFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability from $@.", source.getNode(), "user input"
